from html import escape

def login_html(error=""):
    err=f'<div class="error">{escape(error)}</div>' if error else ''
    return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dollax Login</title><link rel="stylesheet" href="/static/style.css"></head><body class="login"><form class="login-card" method="post" action="/login"><div class="brand big"><div class="brand-mark">D</div><div><b>Dollax</b><small>VPN PANEL</small></div></div><h1>Welcome back</h1><p>Sign in to your panel.</p>{err}<label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="btn primary wide">Sign in</button></form></body></html>'''

def dashboard_html(panel_name="Dollax Panel"):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(panel_name)}</title><link rel="stylesheet" href="/static/style.css"></head><body><div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">D</div><div><b>Dollax</b><small>VPN PANEL</small></div></div><nav><button class="nav active" data-page="dashboard">Overview</button><button class="nav" data-page="inbounds">Inbounds</button><button class="nav" data-page="clients">Clients</button><button class="nav" data-page="settings">Settings</button></nav><button id="logout" class="nav logout">Log out</button></aside><main><header><div><div class="eyebrow">DOLLAX CONTROL CENTER</div><h1 id="title">Overview</h1><p id="subtitle">Manage inbounds and client configurations.</p></div><div class="online"><i></i> ONLINE</div></header><section id="content"></section></main></div><div id="drawer" class="drawer hidden"><div class="drawer-card"><div class="drawer-head"><div><h2 id="drawer-title"></h2><p id="drawer-subtitle"></p></div><button id="drawer-close" class="icon">×</button></div><div id="drawer-body"></div><div id="drawer-actions" class="drawer-actions"></div></div></div><div id="toast"></div><script src="/static/app.js"></script></body></html>'''
